<script>import{t}from'../logic/i18n.js';import{getAllSlugs}from'../logic/wiki.js';let{lang='fa',isOpen=false,currentSlug='home',onNavigate,onClose,onOpen}=$props();const pages=$derived(getAllSlugs());</script>{#if isOpen}<div class="so" role="button" tabindex="-1" onclick={()=>onClose&&onClose()} onkeydown={(e)=>{if(e.key==='Escape'||e.key==='Enter')onClose&&onClose()}}></div>{/if}<div class="st" class:st--h={isOpen} class:st--ltr={lang==='en'} role="button" tabindex="0" onclick={()=>onOpen&&onOpen()} onkeydown={(e)=>{if(e.key==='Enter'||e.key===' ')onOpen&&onOpen()}}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="16" height="16"><path d="M9 18l6-6-6-6"/></svg><span class="tl">{t(lang,'allPages')}</span></div><aside class="sb" class:sb--o={isOpen} class:sb--ltr={lang==='en'}><div class="sh"><span class="st2">{t(lang,'allPages')}</span><button class="sc" onclick={()=>onClose&&onClose()} aria-label={t(lang,'closeSidebar')}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="20" height="20"><path d="M18 6 6 18M6 6l12 12"/></svg></button></div><nav class="sn"><ul class="pl">{#each pages as page(page.slug)}<li><button class="pli" class:pli--a={currentSlug===page.slug} onclick={()=>{if(onNavigate)onNavigate(page.slug);if(onClose&&window.innerWidth<769)onClose()}}><svg class="pi" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg><span class="pt">{page.titles[lang]||page.titles.fa||page.slug}</span></button></li>{/each}</ul></nav></aside><style>.so{position:fixed;inset:0;background:rgba(0,0,0,0.4);z-index:90;animation:fi 200ms ease}@keyframes fi{from{opacity:0}to{opacity:1}}.sb{position:fixed;top:0;bottom:0;right:0;width:var(--sidebar-width);max-width:85vw;background:var(--color-bg-primary);border-left:1px solid var(--color-border);z-index:95;transform:translateX(100%);transitio